'use strict';
let portalMaster=false,portalRole='player',portalView='welcome',wizard=null,wizardStep=0;
const username=()=>C.user()?.email?.replace('@players.new-detroit.invalid','')||'';
function portalShell(title,subtitle,body){$('#app').innerHTML=`<div class="portal"><header class="portal-top"><button id="portal-home" class="portal-brand">N<span>D</span> <small>НЬЮ ДЕТРОИТ</small></button><span class="eyebrow">CHARACTER SYSTEM / 02</span>${C.user()?'<button id="portal-logout">Выйти</button>':''}</header><main class="portal-main"><div class="eyebrow">${portalRole==='master'?'ТЕРМИНАЛ МАСТЕРА':'ЛИЧНОЕ ДЕЛО'}</div><h1 tabindex="-1">${title}</h1><p class="portal-lead">${subtitle}</p>${body}<p id="portal-error" role="alert"></p></main><footer>NEW DETROIT <span>ТВОЯ ИСТОРИЯ. ТВОЙ СЛЕД.</span></footer></div>`;$('#portal-home').onclick=showWelcome;if($('#portal-logout'))$('#portal-logout').onclick=async()=>{try{await C.logout();portalMaster=false;cloudRecord=null;wizard=null;history.replaceState(null,'',location.pathname);showWelcome();}catch(e){portalError(e);}};}
function portalError(e){if($('#portal-error'))$('#portal-error').textContent=e.message;else notify(e.message);}
function showWelcome(){portalView='welcome';portalShell('Город ждёт тебя.','Выбери, с какой стороны истории ты войдёшь в Нью Детроит.',`<div class="role-grid"><button class="role-card" data-role="player"><span class="eyebrow">01 / ЛИЧНАЯ ИСТОРИЯ</span><strong>Игрок</strong><p>Создай персонажа. Открой свои карточки и те, к которым мастер выдал доступ.</p><span class="role-arrow">Войти в город ↗</span></button><button class="role-card" data-role="master"><span class="eyebrow">02 / УПРАВЛЕНИЕ ИГРОЙ</span><strong>Мастер</strong><p>Все персонажи, редактирование карточек и управление доступом игроков.</p><span class="role-arrow">Открыть терминал ↗</span></button></div><p class="hint">Режим мастера доступен только назначенному аккаунту.</p>`);document.querySelectorAll('[data-role]').forEach(b=>b.onclick=async()=>{portalRole=b.dataset.role;if(C.user())await enterPortal();else showLogin();});}
function showLogin(register=false){portalView='login';portalShell(register?'Новый житель.':'С возвращением.',portalRole==='master'?'Вход в терминал мастера. Для существующего аккаунта используй прежние email и пароль.':'Войди по логину или создай аккаунт, чтобы начать свою историю.',`<form id="portal-login" class="panel auth-panel"><label class="field"><span>${register?'Логин':'Логин или email существующего аккаунта'}</span><input name="login" autocomplete="username" required ${register?'pattern="[A-Za-z0-9][A-Za-z0-9_-]{2,31}" minlength="3" maxlength="32"':''}></label>${register?'<p class="hint">3–32 символа: латинские буквы, цифры, дефис и подчёркивание. Регистр не важен.</p>':''}<label class="field"><span>Пароль</span><input name="password" type="password" minlength="6" maxlength="128" autocomplete="${register?'new-password':'current-password'}" required></label>${register?'<p class="hint">От 6 символов, без требований к цифрам или спецсимволам. Запомни логин и пароль: почта для регистрации не нужна.</p>':''}<button type="submit" class="yellow">${register?'Создать аккаунт':'Войти'}</button>${portalRole==='player'?`<button type="button" id="auth-switch">${register?'Уже есть аккаунт':'Зарегистрироваться'}</button>`:''}</form>`);if($('#auth-switch'))$('#auth-switch').onclick=()=>showLogin(!register);$('#portal-login').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type=submit]');b.disabled=true;try{if(register)await C.signup(f.login.value,f.password.value);await C.login(f.login.value,f.password.value);await enterPortal();}catch(err){portalError(err);b.disabled=false;}};}
async function enterPortal(){try{portalMaster=await C.isMaster();if(portalRole==='master'&&!portalMaster){showWelcome();portalError(Error('У этого аккаунта нет прав мастера. Выбери режим игрока.'));return;}const id=cardId();if(id){await openCard(id);return;}await showLibrary();}catch(e){portalError(e);}}
async function showLibrary(){try{await save();if(dirty||saving)throw Error('Есть неотправленные изменения. Дождись сохранения или нажми на статус, чтобы разрешить конфликт.');clearTimeout(saveTimer);cloudRecord=null;portalView='library';history.replaceState(null,'',location.pathname);portalShell(portalRole==='master'?'Все личные дела.':'Мои персонажи.',portalRole==='master'?'Редактируй любую карточку и выдавай игрокам доступ.':`На связи: ${esc(username())}. Здесь только твои и доступные тебе персонажи.`,`<div class="library-toolbar"><button id="new-character" class="yellow">+ Создать персонажа</button><button id="refresh-library">Обновить</button></div><div id="character-grid" class="character-grid" aria-live="polite">Загружаем карточки…</div>`);$('#new-character').onclick=startWizard;$('#refresh-library').onclick=showLibrary;let rows=await C.list();if(portalRole==='player'&&portalMaster){const visible=await Promise.all(rows.map(async r=>r.owner_id===C.user().id||(await C.grants(r.id)).some(g=>g.email===C.user().email.toLowerCase())));rows=rows.filter((r,i)=>visible[i]);}if(portalView!=='library')return;$('#character-grid').innerHTML=rows.length?rows.map(r=>`<button class="character-card" data-character="${esc(r.id)}"><span class="eyebrow">${r.owner_id===C.user().id?'МОЙ ПЕРСОНАЖ':portalRole==='master'?'КАРТОЧКА ИГРОКА':'ОБЩИЙ ДОСТУП'}</span><h2>${esc(r.data.nickname||r.data.name||'Без имени')}</h2><p>${esc((r.data.bio||'История ещё не написана.').slice(0,150))}</p><span class="micro">${new Date(r.updated_at).toLocaleString('ru-RU')}</span><span class="role-arrow">Открыть досье ↗</span></button>`).join(''):'<section class="empty-library"><span class="eyebrow">ДОСЬЕ / 000</span><h2>Твоя история начинается здесь.</h2><p>Карточек пока нет. Нажми «Создать персонажа» — пройдём три шага вместе.</p></section>';document.querySelectorAll('[data-character]').forEach(b=>b.onclick=()=>openCard(b.dataset.character).catch(portalError));}catch(e){portalError(e);}}
const wizardKey=()=>`nd-creation-${C.user().id}`;
function rememberWizard(){try{sessionStorage.setItem(wizardKey(),JSON.stringify({card:wizard,step:wizardStep}));}catch{notify('Черновик не поместился в браузере. Не закрывай страницу до создания карточки.');}}
function startWizard(){wizard=E.blank(D);wizardStep=0;try{const saved=JSON.parse(sessionStorage.getItem(wizardKey()));if(saved){wizard=E.validate(saved.card,D);wizardStep=Math.max(0,Math.min(2,saved.step||0));}}catch{}showWizard();}
function showWizard(){portalView='wizard';const titles=['Кто ты?','На что ты способен?','Что ты умеешь?'];const subtitles=['Все поля необязательны. Имя и история могут появиться уже во время игры.','Распредели четыре значения: 2, 1, 1 и 0. Каждая характеристика отвечает за свой подход.','Распредели 4 + Нейропластичность очков. Один ранг стоит одно очко, максимум — 3.'];portalShell(titles[wizardStep],subtitles[wizardStep],`<ol class="wizard-steps">${['Личность','Характеристики','Навыки'].map((s,i)=>`<li ${i===wizardStep?'aria-current="step"':''} class="${i<=wizardStep?'reached':''}"><span>0${i+1}</span>${s}</li>`).join('')}</ol><form id="wizard-form">${wizardStep===0?`<div class="identity-wizard panel"><div><label class="photo-upload"><span id="photo-preview">${wizard.photo?`<img src="${esc(wizard.photo)}" alt="Портрет персонажа">`:'<b>+</b><span>Фото персонажа</span>'}</span><input id="wizard-photo" type="file" accept="image/jpeg,image/png,image/webp"><span>Выбрать фото</span></label><p class="hint">JPG, PNG или WebP, до 10 МБ.</p><button type="button" id="remove-photo">Убрать фото</button></div><div><div class="two-cols">${wizardField('Имя персонажа','name')}${wizardField('Никнейм персонажа','nickname')}</div>${wizardField('Возраст персонажа','age')}<label class="field"><span>Краткая предыстория</span><textarea name="bio" maxlength="20000" rows="5">${esc(wizard.bio)}</textarea></label></div></div>`:`<p id="wizard-budget" role="status" class="budget"></p><div class="wizard-stats">${(wizardStep===1?D.attributes:D.skills).map((x,i)=>`<article class="panel wizard-stat"><div class="stat-title"><h2>${esc(x.name==='Тень'?'Скрытность':x.name)}</h2><label><span class="sr-only">${esc(x.name)}</span><select name="rank-${i}" data-rank="${i}" aria-label="${esc(x.name)}">${Array.from({length:wizardStep===1?3:4},(_,v)=>`<option value="${v}" ${wizard[wizardStep===1?'attributes':'skills'][i]===v?'selected':''}>${v}</option>`).join('')}</select></label></div><p>${esc(x.description)}</p></article>`).join('')}</div>`}<div class="wizard-actions"><button type="button" id="wizard-back">${wizardStep?'← Назад':'← К списку'}</button><span class="hint">Шаг ${wizardStep+1} из 3</span><button type="submit" class="yellow" id="wizard-next">${wizardStep===2?'Создать персонажа':'Далее →'}</button></div></form>`);
 $('#wizard-back').onclick=()=>{rememberWizard();if(wizardStep){wizardStep--;showWizard();}else showLibrary();};
 if(wizardStep===0){for(const k of ['name','nickname','age','bio'])$('#wizard-form').elements[k].oninput=e=>{wizard[k]=e.target.value;rememberWizard();};$('#wizard-photo').onchange=uploadPortrait;$('#remove-photo').onclick=()=>{wizard.photo='';rememberWizard();showWizard();};}
 else {document.querySelectorAll('[data-rank]').forEach(el=>el.onchange=()=>{wizard[wizardStep===1?'attributes':'skills'][+el.dataset.rank]=+el.value;wizard.hp=3+wizard.attributes[0];rememberWizard();wizardBudget();});wizardBudget();}
 $('#wizard-form').onsubmit=async e=>{e.preventDefault();try{if(wizardStep===1&&!E.derive(wizard,D.catalog).validAttributes)throw Error('Нужны ровно 2, 1, 1 и 0.');if(wizardStep<2){wizardStep++;rememberWizard();showWizard();window.scrollTo(0,0);return;}E.validateCreation(wizard,D);$('#wizard-next').disabled=true;const row=await C.create(E.validate(wizard,D));sessionStorage.removeItem(wizardKey());wizard=null;await openCard(row.id);notify('Персонаж создан. Снаряжение и стартовый бюджет добавим после уточнения экономики.');}catch(err){portalError(err);if($('#wizard-next'))$('#wizard-next').disabled=false;}};
}
function wizardField(label,key){return `<label class="field"><span>${label}</span><input name="${key}" maxlength="${key==='age'?10:200}" value="${esc(wizard[key])}"></label>`;}
function wizardBudget(){const d=E.derive(wizard,D.catalog),el=$('#wizard-budget');el.textContent=wizardStep===1?(d.validAttributes?'Распределение готово: 2 / 1 / 1 / 0':'Нужно распределить: 2 / 1 / 1 / 0'):`Осталось очков: ${d.skillPoints} из ${4+wizard.attributes[2]}`;el.classList.toggle('warning',wizardStep===1?!d.validAttributes:d.skillPoints<0);}
async function uploadPortrait(e){const file=e.target.files[0];if(!file)return;const next=$('#wizard-next');next.disabled=true;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('Выбери JPG, PNG или WebP до 10 МБ');const bitmap=await createImageBitmap(file);const scale=Math.min(1,640/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#111417';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const photo=canvas.toDataURL('image/jpeg',0.8);if(photo.length>500000)throw Error('Фото слишком сложное. Выбери изображение поменьше');wizard.photo=photo;rememberWizard();$('#photo-preview').innerHTML=`<img src="${photo}" alt="Портрет персонажа">`;}catch(err){portalError(err);}finally{next.disabled=false;}}
showWelcome();
if(cardId()){if(C.user())enterPortal();else showLogin();}
function editPortrait(){modal('Фото персонажа','<label class="field"><span>JPG, PNG или WebP, до 10 МБ</span><input id="edit-photo-file" type="file" accept="image/jpeg,image/png,image/webp"></label><button id="clear-photo">Убрать фото</button>');$('#clear-photo').onclick=()=>{card.photo='';changed();closeModal();render();};$('#edit-photo-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('Выбери JPG, PNG или WebP до 10 МБ');const bitmap=await createImageBitmap(file),scale=Math.min(1,640/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#111417';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const photo=canvas.toDataURL('image/jpeg',.8);if(photo.length>500000)throw Error('Фото слишком большое');card.photo=photo;changed();closeModal();render();}catch(e){error(e);}};}
